#include <stdio.h>

/* teste do desafio a-agenda — counter_protocol (03-tdd 3.9.3).
   Dois lados, medidos separado: o cenario 1 LE o caderno que a funcao do
   aluno escreveu; os cenarios 2 e 3 escrevem o caderno NO TESTE e cobram o
   valor devolvido pela leitura; o cenario 4 fecha a volta inteira.
   Cada cenario zera agenda.txt com o modo "w" antes de comecar. */

/* prototipos das funcoes do aluno (o teste declara o que exercita) */
void aAgenda(void);
int somaDasIdades(void);

SM_TEST(a_agenda_grava_uma_linha_por_ficha) {
    FILE *zera = fopen("agenda.txt", "w");
    fclose(zera);

    aAgenda();

    FILE *f = fopen("agenda.txt", "r");
    char linha[80] = "(nada escrito)";
    fgets(linha, 80, f);
    checa_str("a ficha de cima", linha, "ana 30\n",
              "a primeira ficha ocupa a primeira linha, nome e idade");
    fgets(linha, 80, f);
    checa_str("a ficha de baixo", linha, "bruno 31\n",
              "a segunda ficha ocupa a segunda linha, no mesmo formato");
    char fim[80] = "(nada escrito)";
    fgets(fim, 80, f);
    checa_str("nao ha ficha a mais", fim, "(nada escrito)",
              "o caderno acaba na segunda ficha: nenhuma linha extra e aceita");
    fclose(f);
}

SM_TEST(le_duas_fichas_e_soma) {
    FILE *c = fopen("agenda.txt", "w");
    fprintf(c, "clara 20\ndinis 22\n");
    fclose(c);

    checa_int("a soma de duas fichas lidas", somaDasIdades(), 42,
              "20 + 22 = 42: as idades vem do caderno, nao do codigo");
}

SM_TEST(le_tres_fichas_e_soma) {
    FILE *c = fopen("agenda.txt", "w");
    fprintf(c, "edu 7\nflor 9\nglau 11\n");
    fclose(c);

    checa_int("a soma de tres fichas lidas", somaDasIdades(), 27,
