SM_TEST(escreve_e_le_de_volta) {
    FILE *zera = fopen("agenda.txt", "w");
    fclose(zera);

    aAgenda();

    checa_int("a volta inteira", somaDasIdades(), 61,
              "30 + 31 = 61: o que aAgenda gravou e o que somaDasIdades le");
}

