#include <stdio.h>

typedef struct {
    char nome[40];
    int idade;
} Pessoa;

void aAgenda(void) {
    Pessoa ana = {"ana", 30};
    Pessoa bruno = {"bruno", 31};
    FILE *f = fopen("agenda.txt", "w");

    fprintf(f, "%s %d\n", ana.nome, ana.idade);
    fprintf(f, "%s %d\n", bruno.nome, bruno.idade);

    fclose(f);
}

int somaDasIdades(void) {
    Pessoa p = {"", 0};
    int soma = 0;
    FILE *f = fopen("agenda.txt", "r");

    while (fscanf(f, "%s %d", p.nome, &p.idade) == 2) {
        soma = soma + p.idade;
    }

    fclose(f);
    return soma;
}
